import abc
import re

import six
from moler.exceptions import CommandFailure, ParsingDone

from ta_moler.cmd.emssim.genericemssim import GenericEMSSIMCommand

__author__ = "Marcin Usielski"
__copyright__ = "Copyright (C) 2018-2023, Nokia"
__email__ = "marcin.usielski@nokia.com"


@six.add_metaclass(abc.ABCMeta)
class GenericTabular(GenericEMSSIMCommand):
    """Generictabular command class."""

    def __init__(self, connection, columns_as_key=0, prompt=None, newline_chars=None, runner=None):
        """
        Generictabular.

        :param connection: moler connection to device, terminal when command is executed.
        :param columns_as_key: number of columns
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(GenericTabular, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.columns_as_key = columns_as_key
        self.headers = []
        self.headers_col_count = 0
        self.current_ret["dict"] = {}
        self.current_ret["list"] = []

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._error_detected(line)
                self._parse_headers(line)
                self._parse_data_row(line)
            except ParsingDone:
                pass  # line has been fully parsed by one of above parse-methods
        return super(GenericTabular, self).on_new_line(line, is_full_line)

    _re_error = re.compile(r"\|ERROR:(?P<ERROR_MSG>.*)")

    def _error_detected(self, line):
        if self._regex_helper.search_compiled(GenericTabular._re_error, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR_MSG')}"))
            raise ParsingDone

    _re_headers = re.compile(r"(?P<HEADERS>\|\s+(\S+)\s*\|)")

    def _parse_headers(self, line):
        if not self.headers:
            if self._regex_helper.search_compiled(GenericTabular._re_headers, line):
                matched = re.findall(r"\|\s+(\S+)\s*", line)
                if matched:
                    self.headers = matched
                    self.headers_col_count = len(self.headers)
                    raise ParsingDone()

    _re_ornaments = re.compile(r"(?P<ORNAMENTS>={3,}|-{3,})")

    def _parse_data_row(self, line):
        if not self._regex_helper.search_compiled(GenericTabular._re_ornaments, line):
            if self.headers:
                matched = line.split("|")[1:-1]
                if matched:
                    data_col_count = len(matched)
                    if data_col_count == self.headers_col_count:
                        matched = [str(item.strip()) for item in matched]
                        self._parse_line_to_current_result(matched)
                        raise ParsingDone()
                    else:
                        exception = CommandFailure(
                            self,
                            f"Found {self.headers_col_count} columns in headers but {data_col_count} columns in data raw in line: '{line}'",
                        )
                        self.set_exception(exception)

    def _parse_line_to_current_result(self, line):
        key = self._set_key(line)
        if key != "":
            self.current_ret["dict"][key] = {}
            row_dict = dict(zip(self.headers, line))
            self.current_ret["dict"][key].update(row_dict)
            self.current_ret["list"].append(row_dict)
        else:
            self._add_line_to_previous_row(line)

    def _add_line_to_previous_row(self, line):
        for index, name in enumerate(line):
            if name != "":
                which_column = self.headers[index]
                header = self.headers[self.columns_as_key]
                which_row = self.current_ret["list"][-1][header]
                self.current_ret["dict"][which_row][which_column] += f" {name}"
                self.current_ret["list"][-1][which_column] += f" {name}"

    def _set_key(self, line):
        # key = ""
        # if isinstance(self.columns_as_key, (list, tuple)):
        #     for part_key in self.columns_as_key:
        #         column_as_key = part_key
        #         key = '{}_{}'.format(key, line[column_as_key])
        #     key = key[1:]
        # else:
        key = line[self.columns_as_key]
        return key
